import Foundation
import Testing

@testable import TractandaClient

// Independent fixture document: never generated by the production schema/discovery builder.
func discoveryReply(
    callID: String, accountID: String = "00112233-4455-6677-8899-aabbccddeeff", state: String = "metadata-1"
) throws -> Data {
    let capability = "https://tractanda.ai/ns/jmap/1"
    let payload: [String: Any] = [
        "profile": "tractanda.local-session.v1", "username": "test", "state": state,
        "capabilities": [
            "urn:ietf:params:jmap:core": [
                "maxSizeUpload": 0, "maxConcurrentUpload": 1,
                "maxSizeRequest": 8_388_608, "maxConcurrentRequests": 4, "maxCallsInRequest": 8,
                "maxObjectsInGet": 64, "maxObjectsInSet": 64, "collationAlgorithms": ["i;unicode-casemap"],
            ],
            capability: ["integerEncoding": "tagged-int64-decimal-v1"],
        ],
        "accounts": [
            accountID: [
                "name": "Test", "isPersonal": false, "isReadOnly": false,
                "accountCapabilities": [capability: [:] as [String: String]],
            ]
        ],
        "primaryAccounts": [capability: accountID],
    ]
    return try JSONSerialization.data(withJSONObject: [
        "sessionState": state,
        "methodResponses": [["TractandaSession/get", payload, callID]],
    ])
}

private actor AccountTranscript: ItemTransport {
    var requests: [Data] = []
    var auth = "alice"
    var metadata = "metadata-1"
    var concurrentDiscoveries = 0
    var maximumDiscoveries = 0
    func discoveryContext() -> String { auth }
    func changeAuth() { auth = "bob" }
    func changeMetadata() { metadata = "metadata-2" }
    func send(_ request: Data) async throws -> Data {
        requests.append(request)
        let value = try JMAPValue.decode(request)
        let call = value["methodCalls"]!.elements![0].elements!
        let method = call[0].text!
        let id = call[2].text!
        if method == "TractandaSession/get" {
            concurrentDiscoveries += 1
            maximumDiscoveries = max(maximumDiscoveries, concurrentDiscoveries)
            try await Task.sleep(for: .milliseconds(15))
            concurrentDiscoveries -= 1
            return try discoveryReply(callID: id, state: metadata)
        }
        return try JMAPValue.object([
            JMAPMember("sessionState", .string(metadata)),
            JMAPMember("methodResponses", .array([.array([.string(method), call[1], .string(id)])])),
        ]).encoded()
    }
    func calls() throws -> [JMAPInvocation] {
        try requests.flatMap { try JMAPRequest.decode($0).methodCalls }
    }
}

@Test func accountClientDiscoversOnceAndPreservesExplicitSelection() async throws {
    let transport = AccountTranscript()
    let client = JMAPClientContext(transport: transport)
    _ = try await client.send(method: "TractandaStore/info", arguments: .object([]))
    _ = try await client.send(
        method: "TractandaStore/info", arguments: .object([JMAPMember("accountId", .string("foreign"))]))
    _ = try await client.send(method: "Core/echo", arguments: .object([]))
    let calls = try await transport.calls()
    #expect(
        calls.map(\.name) == [
            "TractandaSession/get", "TractandaStore/info", "TractandaStore/info", "Core/echo",
        ])
    #expect(calls[1].arguments["accountId"]?.text == "00112233-4455-6677-8899-aabbccddeeff")
    #expect(calls[2].arguments["accountId"]?.text == "foreign")
    #expect(calls[3].arguments["accountId"] == nil)
}

@Test func concurrentAccountCallsUseSingleFlightDiscovery() async throws {
    let transport = AccountTranscript()
    let context = JMAPClientContext(transport: transport)
    try await withThrowingTaskGroup(of: Void.self) { group in
        for _ in 0..<8 {
            group.addTask {
                _ = try await context.send(method: "TractandaStore/info", arguments: .object([]))
            }
        }
        try await group.waitForAll()
    }
    #expect(try await transport.calls().filter { $0.name == "TractandaSession/get" }.count == 1)
    #expect(await transport.maximumDiscoveries == 1)
}

@Test func metadataChangeRefreshesNextCallWithoutReplayAndAuthGetsNewDiscovery() async throws {
    let transport = AccountTranscript()
    let context = JMAPClientContext(transport: transport)
    _ = try await context.send(method: "TractandaItem/commit", arguments: .object([]))
    await transport.changeMetadata()
    _ = try await context.send(method: "TractandaItem/commit", arguments: .object([]))
    #expect(try await transport.calls().filter { $0.name == "TractandaSession/get" }.count == 1)
    _ = try await context.send(method: "TractandaStore/info", arguments: .object([]))
    await transport.changeAuth()
    _ = try await context.send(method: "TractandaStore/info", arguments: .object([]))
    let calls = try await transport.calls()
    #expect(calls.filter { $0.name == "TractandaSession/get" }.count == 3)
    #expect(calls.filter { $0.name == "TractandaItem/commit" }.count == 2)
}
